package kr.releasepilot.controlplane.analysis;
import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import java.time.Duration;
@Component @ConditionalOnProperty(prefix="releasepilot.analysis",name="enabled",havingValue="true",matchIfMissing=true)public class AnalysisScheduler{private final AnalysisJobPlanner planner;private final AnalysisJobProcessor processor;private final AnalysisJobRecoveryService recovery;private final Duration lease;private final int batch;public AnalysisScheduler(AnalysisJobPlanner planner,AnalysisJobProcessor processor,AnalysisJobRecoveryService recovery,@Value("${releasepilot.analysis.lease-timeout:PT2M}")Duration lease,@Value("${releasepilot.analysis.batch-size:20}")int batch){this.planner=planner;this.processor=processor;this.recovery=recovery;this.lease=lease;this.batch=batch;}@Scheduled(fixedDelayString="${releasepilot.analysis.poll-interval:PT5S}")public void tick(){recovery.recoverExpired(lease,batch);planner.planReady();for(int i=0;i<batch&&processor.processOne();i++){}}}
